    <script>
        // Theme Management
        const themeToggle = document.getElementById('theme-toggle');
        const lightIcon = document.getElementById('theme-icon-light');
        const darkIcon = document.getElementById('theme-icon-dark');
        const htmlEl = document.documentElement;

        function applyTheme(theme) {
            htmlEl.setAttribute('data-theme', theme);
            if (theme === 'dark') {
                lightIcon.classList.add('hidden');
                darkIcon.classList.remove('hidden');
            } else {
                lightIcon.classList.remove('hidden');
                darkIcon.classList.add('hidden');
            }
        }

        const savedTheme = localStorage.getItem('theme') || (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
        applyTheme(savedTheme);

        themeToggle.addEventListener('click', () => {
            const currentTheme = htmlEl.getAttribute('data-theme') || (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
            const newTheme = currentTheme === 'light' ? 'dark' : 'light';

            applyTheme(newTheme);
            localStorage.setItem('theme', newTheme);
        });

        // Auto theme detection
        window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', e => {
            if (!localStorage.getItem('theme')) {
                applyTheme(e.matches ? 'dark' : 'light');
            }
        });

        // API Integration
        const analyzeBtn = document.getElementById('analyze-btn');
        const payloadInput = document.getElementById('payload-input');
        const resultsDiv = document.getElementById('analysis-results');

        analyzeBtn.addEventListener('click', async () => {
            const payload = payloadInput.value.trim();
            if (!payload) {
                alert('Please enter a payload to analyze');
                return;
            }

            analyzeBtn.textContent = '🔄 Analyzing with all engines...';
            analyzeBtn.disabled = true;

            try {
                const response = await fetch('/api/analyze', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({ payload })
                });

                const result = await response.json();
                displayResults(result);
                addToSecurityLogs(result);
                updateMetrics();

            } catch (error) {
                console.error('Analysis failed:', error);
                alert('Analysis failed. Please try again.');
            } finally {
                analyzeBtn.textContent = '🚀 Multi-Engine Analysis';
                analyzeBtn.disabled = false;
            }
        });

        function displayResults(result) {
            const threatLevelClass = getThreatLevelClass(result.threat_level);
            const threatLevelText = getThreatLevelText(result.threat_level);

            resultsDiv.innerHTML = `
                <div class="glass-card p-4 ${threatLevelClass} ${result.threat_level > 70 ? 'critical-pulse' : ''}">
                    <div class="grid md:grid-cols-2 gap-4 mb-4">
                        <div>
                            <h4 class="font-bold text-lg mb-2">🎯 Analysis Results</h4>
