                    <div class="text-xs" style="color: var(--text-secondary);">Uptime</div>
                </div>
            `;
        }

        function updateEngineStatus(engines) {
            const container = document.getElementById('engine-status');
            container.innerHTML = Object.entries(engines).map(([name, engine]) => `
                <div class="engine-status">
                    <span>${name.replace('_', ' ').toUpperCase()}</span>
                    <div class="flex items-center space-x-2">
                        <span class="text-green-400 text-xs">${engine.status}</span>
                        <div class="status-indicator"></div>
                    </div>
                </div>
            `).join('');
        }

        function updateQuantumStatus(quantum) {
            const container = document.getElementById('quantum-status');
            container.innerHTML = `
                <div class="flex justify-between">
                    <span class="text-sm">Entanglement Pairs</span>
                    <span class="text-sm font-bold text-cyan-400">${quantum.entanglement_pairs}</span>
                </div>
                <div class="flex justify-between">
                    <span class="text-sm">Coherence Level</span>
                    <span class="text-sm font-bold text-green-400">${quantum.coherence_level.toFixed(1)}%</span>
                </div>
                <div class="flex justify-between">
                    <span class="text-sm">Decoherence Time</span>
                    <span class="text-sm font-bold text-blue-400">${quantum.decoherence_time}</span>
                </div>
                <div class="flex justify-between">
                    <span class="text-sm">Quantum Advantage</span>
                    <span class="text-sm font-bold text-purple-400">${quantum.quantum_advantage ? 'Active' : 'Inactive'}</span>
                </div>
            `;
        }

        function updateMetrics() {
            // Trigger live updates
            updateSystemStatus();
        }

        // Initialize and start periodic updates
        updateSystemStatus();
        setInterval(updateSystemStatus, 5000);

        // Sample payloads for testing
        const samplePayloads = [
            "SELECT * FROM users WHERE id = 1; DROP TABLE users;",
            "<script>alert('XSS Attack')</script>",
            "'; UNION SELECT password FROM admin_users; --",
            "javascript:document.location=''+document.cookie",
            "Normal safe input text",
            "../../../etc/passwd",
            "rm -rf / --no-preserve-root",
            "X5O!P%@AP[4\\PZX54(P^)7CC)7}$EICAR-STANDARD-ANTIVIRUS-TEST-FILE!$H+H*"
        ];

        payloadInput.addEventListener('focus', () => {
            if (!payloadInput.value) {
                const randomPayload = samplePayloads[Math.floor(Math.random() * samplePayloads.length)];
                payloadInput.placeholder = `Try: ${randomPayload}`;
            }
        });

        // Add random security events
        function simulateSecurityEvents() {
            const events = [
                { type: 'QUANTUM', message: 'Entanglement verified', color: 'text-cyan-400' },
                { type: 'NEURAL', message: 'Model retraining completed', color: 'text-green-400' },
                { type: 'CONSENSUS', message: 'Byzantine agreement reached', color: 'text-purple-400' },
                { type: 'VERIFICATION', message: 'Formal proof validated', color: 'text-blue-400' },
                { type: 'PERFORMANCE', message: 'SIMD acceleration active', color: 'text-yellow-400' },
                { type: 'DISTRIBUTED', message: 'Node synchronization complete', color: 'text-red-400' }
            ];

            const event = events[Math.floor(Math.random() * events.length)];
            const logs = document.getElementById('security-logs');
            const timestamp = new Date().toLocaleTimeString();

            const logEntry = document.createElement('div');
            logEntry.className = event.color;
            logEntry.textContent = `[${timestamp}] [${event.type}] ${event.message}`;

            logs.appendChild(logEntry);
            logs.scrollTop = logs.scrollHeight;

            while (logs.children.length > 25) {
                logs.removeChild(logs.children[3]);
            }
        }

        // Add simulated events every 3-8 seconds
        setInterval(simulateSecurityEvents, Math.random() * 5000 + 3000);
    </script>
</body>
</html>
